function dir$s612(p){
  this.constructor(p);
}
dir$s612.prototype = new DirEvent();
dir$s612.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
  document._dir = this._dir;
}
dir$s612.prototype.afterInit = function(renderType){
  var p = this._dir, g = p.grid(0);
  var exp = {
    t_so_luong: ['@t_so_luong', '[so_luong]'],
	t_tong_trong: ['@t_tong_trong', '[tong_trong]'],
	t_tong_khoi: ['@t_tong_khoi', '[tong_khoi]'],

  }
  p.applyExpression(exp, g, false);

  g.FomulaApplied = {
	"!ty_gia":[],
    "so_luong":["t_so_luong", "t_tong_trong", "t_tong_khoi"],
	"tong_trong":["t_tong_trong"],
	"tong_khoi":["t_tong_khoi"],

  }
  //console.log(JSON.stringify(g.FomulaApplied)); //Gan la ds cong thuc tinh cho cot nao do: 


  p.options.FCColumns = {FC: [], BC: []};
  g.FCColumns = {FC: [], BC: []};

  var oldTG = '', oTG = p.jObject('ma_nt'); //Neu ty gia thay doi
  oTG.focus(function(){ oldTG = oTG.fval(); }).blur(function(){ if (oldTG != oTG.fval()) onExRateChanged(oTG, p);});
  p.applyFCColumns();
  p.applyFCColumns(g);
 // p.setFCHidden(oTG.fval());

  dir$s612DisabledMasterField(p, g);
  dir$s612HiddenColumnByType(p);
  dir$s612HiddenColumnByTran(p);
  dir$s612DisabledMasterPort(p);
  dir$s612DisabledStatusByAction(p);
  dir$s612LoadDataQuote(p);

}

