dir$s612.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$s612HiddenColumnByTran(p);
      break;
    case 'ma_ngv':
