dir$s612.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$s612DisabledMasterField(p, p.grid(gindex));
  return true;
}
function dir$s612DisabledMasterPort(p){

}
function dir$s612DisabledMasterField(p, g){
if (p.options.action !="NEW")
 p.setDisabled(['so_ct','ngay_ct', 'ma_nt','ma_ngv','ma_job','unit_id'], true);

}
function dir$s612HiddenColumnByType(p){
  var v = p.valForm('ma_ngv'), nt = p.valForm('ma_nt'), bc = p.options.struct.baseCurrency;
  var date = new Date();
  if(p.options.action == 'NEW') {
	if(v ==1) {
		p.setInvisible('tt', true);
		p.valForm('ma_kh', "" , true);
		p.valForm('ma_hang', "" , true);
		p.valForm('ma_noi_di', "" , true);
		p.valForm('ma_noi_den', "" , true);
		p.valForm('ma_nv', "" , true);
		p.valForm('id_tg', "" , true);
		p.valForm('ds_cong',"",true);
		p.valForm('ngay_hl',date,true);
		p.valForm('ngay_hld',"",true);
		p.valForm('t_so_luong',"",true);
		p.clearGrid(0);

		return;
	}if(v == 2) {
		p.setInvisible('tt', false);
		p.valForm('ma_kh', "" , true);
		p.valForm('ma_hang', "" , true);
		p.valForm('ma_noi_di', "" , true);
		p.valForm('ma_noi_den', "" , true);
		p.valForm('ma_nv', "" , true);
		p.valForm('id_bg', "" , true);
		p.valForm('ds_cong',"",true);
		p.valForm('ngay_hl',date,true);
		p.valForm('ngay_hld',"",true);
		p.valForm('t_so_luong',"",true);
		p.clearGrid(0);


		return;
	}
  }
}
function dir$s612HiddenColumnByTran(p){
	var gd = p.valForm('ma_gd').trim();
	if (p.options.action == "NEW")
	{
		p.valForm('ma_job',"",true);
		p.valForm('so_job',"",true);


	}

}
function dir$s612LoadDataQuote(p){
	if (p.options.action != "NEW" ) {

		p.request('get_tongtien', '', 'id')

	}
}
function dir$s612HiddenColumnByDay(p){
	var v = p.valForm('ma_dk_ngay');
	if (v == 1) p.request('ma_dk_ngay', '', ['t2_yn','t3_yn','t4_yn','t5_yn','t6_yn','t7_yn','t8_yn']);
	p.setDisabled(['t2_yn','t3_yn','t4_yn','t5_yn','t6_yn','t7_yn','t8_yn'], v == 1);
	}

function dir$s612DisabledStatusByAction(p){
  var o = p.jObject('status');
  if (p.options.action != 'VIEW') o.find("[value=6],[value=7],[value=9]").remove();
}








