					DECLARE @tien_ban NUMERIC(16,2), 
							@chi_ho NUMERIC(16,2),  
							@tien_mua NUMERIC(16,2), 
							@thu_ho NUMERIC(16,2), 
							@tien_ln NUMERIC(16,2), 
							@t_tl_ln NUMERIC(16,2)

					SELECT @tien_mua = ISNULL(SUM(t_tieny2),0), @chi_ho = ISNULL(SUM(t_tienx2),0) FROM m72 WHERE id_dh = @id

					SELECT @tien_ban = ISNULL(SUM(t_tieny2),0), @thu_ho = ISNULL(SUM(t_tienx2),0) FROM m54 WHERE id_dh = @id

					SELECT @tien_ln = @tien_ban - @tien_mua

					IF @tien_mua <> 0
						SELECT @t_tl_ln = ISNULL(ROUND(((@tien_ln)/ABS(@tien_mua)) * 100,2),0)
					ELSE
						SELECT @t_tl_ln = 0

					SELECT @tien_mua [!t_mua] , @chi_ho [!t_chiho],  @tien_ban [!t_ban], @thu_ho [!t_thuho], @tien_ln [!t_ln], @t_tl_ln [!t_tl_ln]






